OutboundDialog::OutboundDialog(AppController* controller,QWidget* parent) : QDialog(parent),controller_(controller) {
    setObjectName("outboundDialog"); setAttribute(Qt::WA_DeleteOnClose); setWindowTitle("出口与服务诊断"); resize(700,470); auto* layout=new QVBoxLayout(this); layout->addWidget(contextNote("服务检测结果仅供参考。","手动查询出口或服务地区特征；经本地内核时按当前模式/规则分流，不代表指定叶子。服务结果仅为页面/API特征的启发式判断，不验证账号、聊天或实际播放。"));
    auto* row=new QHBoxLayout; route_=new CompactComboBox; route_->setObjectName("outboundRoute"); route_->addItem("经本地内核","core"); route_->addItem("直接连接","direct"); row->addWidget(route_); start_=new QPushButton("检测出口"); start_->setObjectName("startIpProbe"); row->addWidget(start_); cancel_=new QPushButton("取消"); row->addWidget(cancel_); row->addStretch(); layout->addLayout(row);
    tabs_=new QTabWidget; tabs_->setObjectName("outboundTabs"); auto* ipPage=new QWidget; auto* ipLayout=new QVBoxLayout(ipPage); value_=new QLabel("未检测"); value_->setObjectName("outboundIp"); value_->setTextFormat(Qt::PlainText); auto font=value_->font(); font.setPointSize(17); font.setWeight(QFont::DemiBold); value_->setFont(font); ipLayout->addWidget(value_);
    details_=new QPlainTextEdit; details_->setObjectName("outboundDetails"); details_->setReadOnly(true); ipLayout->addWidget(details_,1); tabs_->addTab(ipPage,"出口 IP"); auto* servicePage=new QWidget; auto* serviceLayout=new QVBoxLayout(servicePage); services_=new QTableWidget(0,4); services_->setObjectName("serviceDiagnosticsTable"); services_->setHorizontalHeaderLabels({"服务","结果","地区","检测依据"}); services_->setEditTriggers(QAbstractItemView::NoEditTriggers); services_->setSelectionBehavior(QAbstractItemView::SelectRows); services_->setSelectionMode(QAbstractItemView::SingleSelection); services_->verticalHeader()->hide(); services_->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents); services_->horizontalHeader()->setSectionResizeMode(3,QHeaderView::Stretch); serviceLayout->addWidget(services_,1); serviceHint_=new QLabel; serviceHint_->setWordWrap(true); serviceLayout->addWidget(serviceHint_); auto* serviceActions=new QHBoxLayout; serviceActions->addStretch(); evidence_=new QPushButton("查看依据"); evidence_->setObjectName("viewServiceEvidence"); serviceActions->addWidget(evidence_); retest_=new QPushButton("重测所选"); serviceActions->addWidget(retest_); serviceLayout->addLayout(serviceActions); connect(evidence_,&QPushButton::clicked,this,&OutboundDialog::showServiceEvidence); connect(services_,&QTableWidget::doubleClicked,this,[this] { showServiceEvidence(); }); tabs_->addTab(servicePage,"服务地区"); layout->addWidget(tabs_,1); auto* actions=new QDialogButtonBox(QDialogButtonBox::Close); actions->button(QDialogButtonBox::Close)->setText("关闭"); layout->addWidget(actions); connect(actions,&QDialogButtonBox::rejected,this,&QDialog::reject);
    connect(start_,&QPushButton::clicked,this,[this] { const bool core=route_->currentData().toString()=="core"; if (tabs_->currentIndex()==1) controller_->startServiceProbe(core); else controller_->startIpProbe(core); }); connect(cancel_,&QPushButton::clicked,controller_,&AppController::cancelOutboundDiagnostics); connect(route_,&QComboBox::activated,controller_,&AppController::cancelOutboundDiagnostics); connect(tabs_,&QTabWidget::currentChanged,this,&OutboundDialog::updateView); connect(services_,&QTableWidget::itemSelectionChanged,this,[this] { evidence_->setEnabled(services_->currentRow()>=0); const auto& state=controller_->state(); retest_->setEnabled(services_->currentRow()>=0&&!controller_->outboundDiagnostics()->busy()&&!state.busy&&!state.exiting&&(route_->currentData().toString()=="direct"||state.ready)); }); connect(retest_,&QPushButton::clicked,this,[this] { const auto* item=services_->item(services_->currentRow(),0); if (item) controller_->startServiceProbe(route_->currentData().toString()=="core",item->data(Qt::UserRole).toString()); });
    connect(controller_->outboundDiagnostics(),&OutboundDiagnostics::changed,this,&OutboundDialog::updateView); connect(controller_,&AppController::stateChanged,this,&OutboundDialog::updateView); updateView();
}
OutboundDialog::~OutboundDialog() { controller_->cancelOutboundDiagnostics(); }
void OutboundDialog::showServiceEvidence() {
    const auto* item=services_->item(services_->currentRow(),0); if (!item) return; const auto result=controller_->outboundDiagnostics()->result(); QJsonObject selected; for (const auto& value:result.value("services").toArray()) if (value.toObject().value("id")==item->data(Qt::UserRole)) selected=value.toObject(); if (selected.isEmpty()) return;
    if (serviceEvidence_) serviceEvidence_->close(); const auto known=[](QJsonValue value) { const auto text=value.toVariant().toString(); return text.isEmpty()?QString("未知"):text; };
    const auto status=selected.value("http_status"); const auto label=selected.value("state").toString(); const auto path=result.value("route")=="core"?QString("经内核 · %1模式").arg(result.value("mode").toString("未知")):result.value("route")=="direct"?QString("直连"):QString("未知");
    const auto text=QStringList{"服务："+known(selected.value("name")),"结果："+(label=="supported"?QString("疑似支持"):label=="restricted"?QString("受限"):QString("未知")),"地区："+known(selected.value("region")),"检测依据："+known(selected.value("evidence")),"目标地址："+known(selected.value("target")),"HTTP 状态："+(status.isDouble()?QString::number(status.toInt()):QString("未知")),"采样时间（UTC）："+known(selected.value("measured_utc")),"实际请求 IP："+known(selected.value("destination_ip")),"传输路径："+path,"核心返回链："+known(result.value("chain")),"", "仅为页面/API特征的启发式结果；不验证账号、聊天或实际播放。HTTP403/超时/人机验证不直接等同地区限制。"}.join('\n');
    auto* dialog=new QDialog(this); serviceEvidence_=dialog; dialog->setAttribute(Qt::WA_DeleteOnClose); dialog->setObjectName("serviceEvidenceSnapshot"); dialog->setWindowTitle("服务检测依据 · 打开时快照"); dialog->resize(560,400); auto* layout=new QVBoxLayout(dialog); auto* details=new QPlainTextEdit(text); details->setObjectName("serviceEvidenceText"); details->setReadOnly(true); details->setWordWrapMode(QTextOption::WrapAnywhere); details->setHorizontalScrollBarPolicy(Qt::ScrollBarAlwaysOff); layout->addWidget(details,1); auto* actions=new QDialogButtonBox(QDialogButtonBox::Close); actions->button(QDialogButtonBox::Close)->setText("完成"); auto* copy=actions->addButton("复制依据",QDialogButtonBox::ActionRole); layout->addWidget(actions); connect(actions,&QDialogButtonBox::rejected,dialog,&QDialog::reject); connect(copy,&QPushButton::clicked,dialog,[text] { QApplication::clipboard()->setText(text); }); dialog->show();
}
void OutboundDialog::updateView() {
    const auto diagnostics=controller_->outboundDiagnostics(); const auto& result=diagnostics->result(); const bool running=diagnostics->busy(); if (serviceEvidence_&&(result.isEmpty()||running)) serviceEvidence_->close(); const auto& state=controller_->state(); route_->setEnabled(!running&&!state.busy&&!state.exiting); start_->setEnabled(!running&&!state.busy&&!state.exiting&&(route_->currentData().toString()=="direct"||state.ready)); cancel_->setEnabled(running);
    if (serviceHint_) serviceHint_->setText(running?"检测进行中 · "+result.value("current_service").toString("确认路径"):(result.contains("error")?result.value("error").toString():QString()));
    start_->setText(tabs_->currentIndex()==1?"检测全部服务":"检测出口"); cancel_->setText("取消并清空"); retest_->setEnabled(services_->currentRow()>=0&&start_->isEnabled()); evidence_->setEnabled(services_->currentRow()>=0);
    const auto rows=result.value("services").toArray(); const QSignalBlocker block(services_); const int selected=services_->currentRow(); services_->setRowCount(rows.size()); for (int i=0;i<rows.size();++i) { const auto row=rows[i].toObject(); const auto state=row.value("state").toString(); const QStringList values{row.value("name").toString(),state=="restricted"?"受限":state=="supported"?"疑似支持":"未知",row.value("region").toString("—"),row.value("evidence").toString()}; for (int col=0;col<values.size();++col) { auto* item=new QTableWidgetItem(values[col]); item->setToolTip(values[3]+"\n目标："+row.value("target").toString()+"\n时间："+row.value("measured_utc").toString()+"\n路径："+result.value("route").toString()+" · "+result.value("mode").toString()+"\n实际请求地址："+row.value("destination_ip").toString()); if (!col) { item->setData(Qt::UserRole,row.value("id")); item->setIcon(UiIcons::service(row.value("id").toString())); } services_->setItem(i,col,item); } } if (selected>=0&&selected<rows.size()) services_->selectRow(selected);
    value_->setText(running&&result.value("kind")!="services"?"检测中…":result.contains("ip")?result.value("ip").toString():result.contains("error")?"未获得结果":"未检测");
    if (result.isEmpty()) { details_->setPlainText(running?"正在检查路径并发出请求…":""); return; }
    const bool core=result.value("route")=="core"; const auto time=QDateTime::fromString(result.value("measured_utc").toString(),Qt::ISODateWithMs).toLocalTime(); QStringList lines{"目标："+result.value("target").toString(),"时间："+time.toString("yyyy-MM-dd HH:mm:ss"),"传输："+(core?QString("经已确认受控内核 127.0.0.1:%1 · %2模式").arg(result.value("mixed_port").toInt()).arg(result.value("mode").toString()):QString("直连，不使用系统代理"))};
    if (result.contains("error")) lines.append("结果："+result.value("error").toString());
    else { lines.append("地区："+result.value("country").toString("未知")+" / "+result.value("region").toString("未知")); lines.append("ASN："+result.value("asn").toString("未知")+" · "+result.value("asn_organization").toString()); lines.append("ISP："+result.value("isp").toString("未知")); lines.append("实际请求目标："+result.value("response_host").toString()+" → "+result.value("destination_ip").toString()); if (core) lines.append("节点链："+result.value("chain").toString()); } details_->setPlainText(lines.join('\n'));
}
